655: _placeholder_rule_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
656: # shellcheck source=../lib/status-classifier.sh
657: source "${_placeholder_rule_dir}/../lib/status-classifier.sh"
